import re,os,sys
root=sys.argv[1]
files=["README.md","docs/01-framework.md","docs/02-engineer-guide.md","docs/03-rollout-plan.md","docs/04-compliance-mapping.md","docs/05-threat-model.md","docs/06-problem-control-map.md","docs/adr/README.md","diagrams/README.md","examples/README.md"]
def slug(h):
    h=h.strip().lower()
    h=re.sub(r'[^\w\- ]','',h)
    return h.replace(' ','-')
def anchors(p):
    a=set()
    for l in open(p,encoding='utf-8'):
        m=re.match(r'^(#+)\s+(.*)',l)
        if m: a.add(slug(m.group(2)))
    return a
for f in files:
    p=os.path.join(root,f)
    txt=open(p,encoding='utf-8').read()
    for m in re.finditer(r'\]\(([^)\s]+)\)',txt):
        t=m.group(1)
        if t.startswith('http'): continue
        path,_,anc=t.partition('#')
        tp=os.path.normpath(os.path.join(os.path.dirname(p),path)) if path else p
        if not os.path.exists(tp): print("MISSING",f,t); continue
        if anc and tp.endswith('.md') and anc not in anchors(tp): print("BADANCHOR",f,t)
EOF
